import{_ as s,c as i,o as a,j as n,Y as o,t as d}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"numfmt | x-cmd man (man1) | Convert numbers from/to human-readable strings","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | numfmt - Convert numbers from/to human-readable strings","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"numfmt | x-cmd man (man1) | Convert numbers from/to human-readable strings"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | numfmt - Convert numbers from/to human-readable strings"}]]},"headers":[],"params":{"isMan":true,"man":"numfmt","category":"man1","desc":"Convert numbers from/to human-readable strings"},"relativePath":"man1/numfmt.md","filePath":"man1/[man].md"}'),r={name:"man1/numfmt.md"},l={class:"visually-hidden"};function h(e,t,p,u,g,c){return a(),i("div",null,[n("h1",l,d(e.$params.man),1),t[0]||(t[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>numfmt - Convert numbers from/to human-readable strings</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>numfmt</strong> [<em>OPTION</em>]... [<em>NUMBER</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Reformat NUMBER(s), or the numbers from standard input if none are specified.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>--debug</strong></dt><dd>print warnings about invalid input</dd><dt><strong>-d</strong>, <strong>--delimiter</strong>=<em>X</em></dt><dd>use X instead of whitespace for field delimiter</dd><dt><strong>--field</strong>=<em>FIELDS</em></dt><dd>replace the numbers in these input fields (default=1); see FIELDS below</dd><dt><strong>--format</strong>=<em>FORMAT</em></dt><dd>use printf style floating-point FORMAT; see FORMAT below for details</dd><dt><strong>--from</strong>=<em>UNIT</em></dt><dd>auto-scale input numbers to UNITs; default is &#39;none&#39;; see UNIT below</dd><dt><strong>--from-unit</strong>=<em>N</em></dt><dd>specify the input unit size (instead of the default 1)</dd><dt><strong>--grouping</strong></dt><dd>use locale-defined grouping of digits, e.g. 1,000,000 (which means it has no effect in the C/POSIX locale)</dd><dt><strong>--header</strong>[=<em>N</em>]</dt><dd>print (without converting) the first N header lines; N defaults to 1 if not specified</dd><dt><strong>--invalid</strong>=<em>MODE</em></dt><dd>failure mode for invalid numbers: MODE can be: abort (default), fail, warn, ignore</dd><dt><strong>--padding</strong>=<em>N</em></dt><dd>pad the output to N characters; positive N will right-align; negative N will left-align; padding is ignored if the output is wider than N; the default is to automatically pad if a whitespace is found</dd><dt><strong>--round</strong>=<em>METHOD</em></dt><dd>use METHOD for rounding when scaling; METHOD can be: up, down, from-zero (default), towards-zero, nearest</dd><dt><strong>--suffix</strong>=<em>SUFFIX</em></dt><dd>add SUFFIX to output numbers, and accept optional SUFFIX in input numbers</dd><dt><strong>--to</strong>=<em>UNIT</em></dt><dd>auto-scale output numbers to UNITs; see UNIT below</dd><dt><strong>--to-unit</strong>=<em>N</em></dt><dd>the output unit size (instead of the default 1)</dd><dt><strong>-z</strong>, <strong>--zero-terminated</strong></dt><dd>line delimiter is NUL, not newline</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h3 id="unit-options" tabindex="-1">UNIT options: <a class="header-anchor" href="#unit-options" aria-label="Permalink to &quot;UNIT options:&quot;">​</a></h3><dl><dt>none</dt><dd>no auto-scaling is done; suffixes will trigger an error</dd><dt>auto</dt><dd>accept optional single/two letter suffix:</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1K</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1Ki</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1024,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000000,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1Mi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1048576,</span></span></code></pre></div><dl><dt>si</dt><dd>accept optional single letter suffix:</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1K</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000000,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">..</span></span></code></pre></div><dl><dt>iec</dt><dd>accept optional single letter suffix:</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1K</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1024,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1048576,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">..</span></span></code></pre></div><dl><dt>iec-i</dt><dd>accept optional two-letter suffix:</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1Ki</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1024,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1Mi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1048576,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">..</span></span></code></pre></div><h3 id="fields-supports-cut-1-style-field-ranges" tabindex="-1">FIELDS supports <strong>cut</strong>(1) style field ranges: <a class="header-anchor" href="#fields-supports-cut-1-style-field-ranges" aria-label="Permalink to &quot;FIELDS supports **cut**(1) style field ranges:&quot;">​</a></h3><dl><dt>N</dt><dd>N&#39;th field, counted from 1</dd><dt>N-</dt><dd>from N&#39;th field, to end of line</dd><dt>N-M</dt><dd>from N&#39;th to M&#39;th field (inclusive)</dd><dt><strong>-M</strong></dt><dd>from first to M&#39;th field (inclusive)</dd><dt>-</dt><dd>all fields</dd></dl><p>Multiple fields/ranges can be separated with commas</p><p>FORMAT must be suitable for printing one floating-point argument &#39;%f&#39;. Optional quote (%&#39;f) will enable <strong>--grouping</strong> (if supported by current locale). Optional width value (%10f) will pad output. Optional zero (%010f) width will zero pad the number. Optional negative values (%-10f) will left align. Optional precision (%.1f) will override the input determined precision.</p><p>Exit status is 0 if all input numbers were successfully converted. By default, numfmt will stop at the first conversion error with exit status 2. With <strong>--invalid=</strong>&#39;fail&#39; a warning is printed for each conversion error and the exit status is 2. With <strong>--invalid=</strong>&#39;warn&#39; each conversion error is diagnosed, but the exit status is 0. With <strong>--invalid=</strong>&#39;ignore&#39; conversion errors are not diagnosed and the exit status is 0.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><p><code>$ numfmt --to=si 1000</code></p></blockquote><blockquote><p>-&gt; &quot;1.0K&quot;</p></blockquote><blockquote><p><code>$ numfmt --to=iec 2048</code></p></blockquote><blockquote><p>-&gt; &quot;2.0K&quot;</p></blockquote><blockquote><p><code>$ numfmt --to=iec-i 4096</code></p></blockquote><blockquote><p>-&gt; &quot;4.0Ki&quot;</p></blockquote><blockquote><p><code>$ echo 1K | numfmt --from=si</code></p></blockquote><blockquote><p>-&gt; &quot;1000&quot;</p></blockquote><blockquote><p><code>$ echo 1K | numfmt --from=iec</code></p></blockquote><blockquote><p>-&gt; &quot;1024&quot;</p></blockquote><blockquote><p><code>$ df -B1 | numfmt --header --field 2-4 --to=si</code> <br> &gt; <code>$ ls -l | numfmt --header --field 5 --to=iec</code> <br> &gt; <code>$ ls -lh | numfmt --header --field 5 --from=iec --padding=10</code> <br> &gt; <code>$ ls -lh | numfmt --header --field 5 --from=iec --format %10f</code></p></blockquote><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Assaf Gordon.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/numfmt%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/numfmt\\</a>&gt; <br> or available locally via: info &#39;(coreutils) numfmt invocation&#39;</p>',42))])}const k=s(r,[["render",h]]);export{f as __pageData,k as default};
